    $("tl-speed").addEventListener("change", function (e) { S.speed = +e.target.value; writeHash(); });
    $("tl-mode").addEventListener("change", function (e) { S.win = +e.target.value; renderTL(); drawHist(); writeHash(); });
    $("theme-select").addEventListener("change", function (e) { setTheme(e.target.value, true); });
